;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                               ;
; CN00 SPACE CODE               ;
;                               ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

        .org $C000+$0100*SLOT


        BIT IORTS       ; SET THE V-FLAG
        BVS BENTRY      ; <ALWAYS>
        SEC
        .byte $90         ; OPCODE FOR BCC
        CLC
        CLV
        BVC BENTRY      ; <ALWAYS> SKIP AROUND PASCAL 1.1 ENTRY


        .byte $01         ; GENERIC SIGNATURE BYTE
        .byte $31         ; DEVICE SIGNATURE BYTE
        .byte <PINIT
        .byte <PREAD
        .byte <PWRITE
        .byte <PSTATUS

;;;;;;;;;;;;;;;;;;;
;                 ;
;  BASIC ENTRIES  ;
;                 ;
;;;;;;;;;;;;;;;;;;;

IENTRY: SEC             ; BASIC INPUT ENTRY
        .byte $90         ; OPCODE FOR BCC
OENTRY: CLC             ; BASIC OUTPUT ENTRY
        CLV

BENTRY: STA CHARACTER
        STX ZPTEMP      ; INPUT BUFFER INDEX
        TXA             ; SAVE X AND Y REGS ON STACK
        PHA
        TYA
        PHA
        JSR BSETUP
        JMP BINIT

;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                          ;
;  DISK INTERFACE ENTRIES  ;
;                          ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;

DISK: CLC             ; PRODOS DRIVER ENTRY
        BCC SETUP
        SEC             ; SMARTPORT DRIVER ENTRY
SETUP: JSR DSETUP
        JMP COMMON

DENTRY: JSR DSETUP
        JMP BOOT

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                                ;
;  NEW PASCAL INTERFACE ENTRIES  ;
;                                ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PINIT: JSR PASCALINIT
        LDX #0          ; NO ERROR POSSIBLE
        RTS
PREAD: JMP PASCALREAD
PWRITE: JMP PASCALWRITE
;
; NEW PASCAL STATUS REQUEST
;
; A-REG=0 -> READY FOR OUTPUT?
; A-REG=1 -> HAS INPUT BEEN RECEIVED?
;
PSTATUS: LSR A           ; SAVE REQUEST TYPE IN CARRY
        JSR PENTRY      ; (PRESERVES CARRY)
        BCS PSTATIN
        JSR SROUT       ; READY FOR OUTPUT?
        BEQ PSTATUS2
        CLC
        BCC PSTATUS2    ; CARRY CLEAR EOR NOT READY

PSTATIN: JSR SRIN        ; SETS CARRY CORRECTLY
PSTATUS2: LDA STSBYTE,X  ; GET ERROR FLAGS
        TAX
        RTS

;;;;;;;;;;;;;;;;;;;;;;;;
; SHARED SETUP ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;;;
BSETUP: LDY #$10*SLOT   ; Y-REG WILL GENERALLY BE $N0
        STY SLOT16
DSETUP: LDX #$C0+SLOT   ; X-REG WILL GENERALLY BE $CN
        STX MSLOT
        STA ROMSOFF     ; SWITCH OUT OTHER $C800 ROMS
        RTS

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; ROUTINE TO SEND A CHARACTER TO ANOTHER CARD ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
SENDCD: LDX #3
SAVEHOOK: LDA CSWL,x
        PHA
        DEX
        BPL SAVEHOOK
;
; PUT CARD ADDRESS IN HOOK
;
        LDX MSLOT
        LDA CHNBYTE,X
        STA CSWL
        LDA STATEFLG,X  ; GET SLOT #
        AND #$38
        LSR A
        LSR A
        LSR A
        ORA #$C0        ; FORM $CN
        STA CSWH
;
; OUTPUT TO THE PERIPHERAL
;
        LDA CHARACTER
        PHA
        ORA #$80        ; 80 COL BOARDS WANT HI-BIT ON
        JSR COUT
;
; RESTORE EVERYTHING THE OTHER CARD MAY HAVE CLOBBERED
;
        PLA
        STA CHARACTER
        JSR BSETUP
;
; PUT BACK CSWL INTO CHNBYTE
;
        LDA CSWL
        STA CHNBYTE,X

        LDX #0
RESTORHOOK: PLA
        STA CSWL,X
        INX
        CPX #4
        BCC RESTORHOOK

        LDX MSLOT
        RTS

        .res $0100-$10-<*

;;;;;;;;;;;;;;;;;;
;                ;
;  CONFIG ENTRY  ;
;                ;
;;;;;;;;;;;;;;;;;;

CONFIG: JSR DSETUP
        JMP CFG

        .byte $4F, $6C, $53, $63


        .byte $41, $50, $50, $4C, $45


        .byte <DISK

; C800 high level.

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                               ;
; APPLE II SSC FIRMWARE         ;
;                               ;
;   BY LARRY KENYON             ;
;                               ;
;    -JANUARY 1981-             ;;;;;;;;;;;;;;
;                                            ;
; (C) COPYRIGHT 1981 BY APPLE COMPUTER, INC. ;
;                                            ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                               ;
; C800 SPACE: HIGH LEVEL STUFF  ;
;                               ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; PASCAL 1.0 INIT ENTRY ;
;;;;;;;;;;;;;;;;;;;;;;;;;

        .org $C800

PASCALINIT: JSR PENTRY   ; PASCAL 1.0 INITIALIZATION ENTRY
        LDA #$16        ; NO XOFF, ECHO, LF EAT, OR LF GEN
INIT1: PHA             ; GOES TO MISCFLG AFTER MODIFICATION
        LDA #0
        STA STATEFLG,X
        STA DELAYFLG,X
        STA HANDSHKE,X
        STA STSBYTE,X
        STA PWDBYTE,X
        STA COLBYTE,X
        LDA DIPSW2,Y    ; SET LF GEN OPTION FROM D2-S5
        STA ZPTMP2      ; SAVE FOR LATER
        LSR A           ; S5-> CARRY
        LSR A           ; IF S5=ON=0 THEN LEAVE MISCFLG ALONE
        BCC INIT1A
        PLA             ; OTHERWISE, MAKE SURE LF GEN
        AND #$FE        ;  ENABLE IS RESET
        PHA
INIT1A: CLV             ; V WILL BE CLEAR FOR CIC MODE
        LDA DIPSW1,Y
        LSR A           ; SIC MODES SET CARRY
        BCS INIT2       ; BRANCH FOR SIC MODES
        LSR A
        BCS INIT2B      ; PPC MODE BRANCH
        LDA #$01        ; CTL-A
        BNE INIT5       ; <ALWAYS> CIC MODE BRANCH

INIT2: LSR A           ; SET CARRY FOR P8A
        LDA #$03        ; SET ETX AS DEFAULT INQUIRY CHAR
        BCS INIT2A      ; BRANCH FOR P8A
        LDA #$80        ; FOR P8 SET AUTO CR GEN
INIT2A: STA STATEFLG,X
INIT2B: BIT IORTS       ; SET V-FLAG FOR PPC, SIC MODES
        LDA ZPTMP2
        AND #$20        ; SET CR DELAY
        EOR #$20        ; SO 1=ENB, 0=DISABLE
        STA DELAYFLG,X  ; FROM D2-S2

        BVS INIT3       ; <ALWAYS> BRANCH AROUND PASCAL
;;;;;;;;;;;;;;;;;;;;;;;;;
; PASCAL 1.0 READ ENTRY ;
; (MUST BE AT $C84D)    ;
;;;;;;;;;;;;;;;;;;;;;;;;;
PREAD0: JSR PASCALREAD  ; DO PASCAL 1.1 READ
        LDX MSLOT       ; MODIFY FOR 1.0
        STA STSBYTE,X   ; CHARACTER READ
        RTS
;;;;;;;;;;;;;;;;;;;;;;;;
; NOW WHERE WERE WE??? ;
;;;;;;;;;;;;;;;;;;;;;;;;

INIT3: LDA ZPTMP2      ; PPC, SIC MODES USE SWITCHES
        LSR A           ; TO SET PWIDTH, CR DELAY
        LSR A
        AND #$03
        TAY
        BEQ INIT4

        PLA             ; RESET VIDEO ENABLE FOR PWIDTH#40
        AND #$7F
        PHA

INIT4: LDA PWDTBL,Y
        STA PWDBYTE,X
        LDY SLOT16

        PLA             ; CLEAR CIC BIT IN FUTURE MISCFLG
        AND #$95        ;  (AND TABBING, XOFF AND LF EAT BITS)
        PHA
        LDA #$09        ; CTL-I

INIT5: STA CMDBYTE,X   ; CMD ESC CHAR (IGNORED FOR SIC MODES)
        PLA
        STA MISCFLG,X   ; SET MISCFLG FLAGS
;
; NOW FOR THE ACIA INITIALIZATION ROUTINE
;
INITACIA: LDA ZPTMP2     ; DIPSW2
        PHA
        AND #$A0        ; DATA BIT OPTIONS FOR CIC MODE
        BVC INITACIA1   ; BRANCH FOR CIC MODE
        AND #$80        ; 8 DATA, 1 OR 2 STOP FOR SIC, PPC
INITACIA1: JSR DATACMD1  ; SET CONTROL REG
        JSR BAUDCMD1    ; SET DIPSWITCH BAUD RATE
        PLA
        AND #$0C        ; PARITY OPTIONS FOR CIC MODE
        BVC INITACIA2   ; BRANCH FOR CIC MODE
        LDA #$0         ; DISABLE PARITY FOR SIC, PPC MODES
INITACIA2: ASL A
        ASL A
        ASL A
        ORA #$0B
        STA CMDREG,Y
        LDA RDREG,Y     ; THROW OUT THE STRANGE STUFF
        RTS
;;;;;;;;;;;;;;;;;;;;;;;
; PASCAL READ ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;;
PASCALREAD: JSR PENTRY   ; SHARED BY BOTH PASCAL VERSIONS
PASCALREAD1: JSR GETCHAR ; GET ACIA/KBD DATA
        AND #$7F        ; CLEAR HIGH BIT FOR PASCAL
PASEXIT: LDY MSLOT
        LDX STSBYTE,Y   ; ERROR STATUS-> X-REG
        RTS
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; GETCHAR ROUTINE WAITS FOR  ;
;  THE NEXT CHAR FROM EITHER ;
;  THE ACIA OR KEYBOARD (IF  ;
;  ENABLED).  USED BY PASCAL ;
;  READ ROUTINE, XON WAIT,   ;
;  AND ACK WAIT. DATA IS RE- ;
;  TURNED IN THE A=REGISTER  ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
GETCHAR: JSR INPUT       ; ACIA DATA?
        BCS GETCHAR1
        JSR CKKBD       ; KEYBOARD INPUT?
        BCC GETCHAR
GETCHAR1: RTS            ; EXIT WHEN WE HAVE SOMETHING

; HILEV.

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                               ;
; APPLE II SSC FIRMWARE         ;
;                               ;
;   BY LARRY KENYON             ;
;                               ;
;    -JANUARY 1981-             ;;;;;;;;;;;;;;
;                                            ;
; (C) COPYRIGHT 1981 BY APPLE COMPUTER, INC. ;
;                                            ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;                               ;
; CIC, SIC, PPC MODE HIGH-LEVEL ;
;                               ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; CIC EXIT ROUTINE . . .        ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CICEXIT: JSR CHECKTERM   ; SEE IF WE'VE ENTERED TERMINAL MODE
;;;;;;;;;;;;;;;;;;;;;;
; BASIC EXIT ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;
BASICEXIT: PLA
        TAY
        PLA
        TAX
        JMP BEXIT
;;;;;;;;;;;;;;;;;;;;;;;
; BASIC INPUT ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;;
BINPUT: BEQ BINACIA     ; BRANCH IF NOT CIC MODE
        LDA BUFBYTE,X   ; INPUT BUFFER FULL?
        BPL BINKBD
        LSR BUFBYTE,X   ; RESET BUFFER FULL
        BNE BINACIA1    ; <ALWAYS>

BINKBD: JSR GETKBD      ; KEYBOARD DATA?
        BCC BINACIA

BINEND: LDA DELAYFLG,X
        AND #$C0        ; TRANSLATE LOWERCASE TO UPPERCASE?
        BEQ BINEND1     ; IF SO, LET THE MONITOR DO IT
        LDA CHARACTER   ; IF NOT, SET FLAG IF
        CMP #$E0        ;  THIS IS A LOWERCASE CHAR
        BCC BINEND1     ;  FOR INPUT BUFFER CORRECTION
        LDA STATEFLG,X  ;  (CIRCUMVENT APPLE MONITOR)
        ORA #$40
        STA STATEFLG,X

BINEND1: PLP
        BEQ BASICEXIT   ; BRANCH IF NOT CIC MODE
        BNE CICEXIT     ; <ALWAYS> CHECK TO SEE IF WE
                        ;  ENTERED TERM MODE (VIA KYBD ESCAPE)
BINACIA: JSR INPUT       ; ACIA DATA?
        BCC BINKBD
BINACIA1: JSR RESTORE    ; DO BASIC CURSED DUTY
        PLP
        PHP             ; GET CIC MODE INDICATOR
        BEQ BINEND      ; SKIP IF NOT CIC MODE
        JSR CKINPUT     ; LOOK FOR INPUT STREAM SPECIAL CHARS
        JMP BINEND
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; SIC, PPC BASIC OUTPUT ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
SEROUT: JSR CMDSEQCK    ; CHECK FOR A COMMAND SEQUENCE
        BCS BASICEXIT   ; BRANCH IF WE WERE IN COMMAND MODE
        LDA CHARACTER   ; SAVE CHAR ON STACK
        PHA
        LDA MISCFLG,X   ; IF VIDEO OR TABBING ENABLED,
        AND #$C0        ;  DON'T MESS WITH THE CURSOR
        BNE TABCHECK

        LDA CH          ; CHECK FOR COMMA TABBING
        BEQ NOTAB       ; IF CH=0, THERE WAS NO TAB OR COMMA
        CMP #8          ; INTEGER BASIC COMMA?
        BEQ COMMA
        CMP #16         ; APPLESOFT COMMA?
        BNE TABCHECK
COMMA: ORA #$F0
        AND COLBYTE,X   ; SET COL TO PREVIOUS TAB
        CLC
        ADC CH          ; THEN INCREMENT TO NEXT TAB
        STA CH

TABCHECK: LDA COLBYTE,X
        CMP CH          ; IS TABBING NEEDED?
        BEQ NOTAB       ; IF EQUAL THEN NO TAB NEEDED
        LDA #$A0        ; SPACE FOR FORWARD TAB
        BCC TAB1
        LDA MISCFLG,X   ; DON'T BACKSPACE UNLESS TABBING
        ASL A           ;  OPTION IS ENABLED
        BPL NOTAB
        LDA #$88        ; BACKSPACE FOR BACKTAB
TAB1: STA CHARACTER
        BIT IORTS       ; SET V=1 TO INDICATE TABBING
        PHP             ; SAVE TABBING INDICATOR
        BVS TAB2        ; <ALWAYS> AROUND BATCH MOVE ENTRY
        NOP
;;;;;;;;;;;;;;;;;;;;;;;;
; SHORT BATCH MOVE:    ;
;  LOCATE AT $C93D FOR ;
;  COMPATIBILITY WITH  ;
;  SIC P8 BLOCK MOVE.  ;
;;;;;;;;;;;;;;;;;;;;;;;;
BATCHIN: BIT IORTS
        .byte $50         ; DUMMY BVC
BATCHOUT: CLV            ; V=0 FOR OUTPUT ENTRY
        LDX MSLOT
        JMP BATCHIO
;;;;;;;;;;;;;;
; BURP . . . ;
;;;;;;;;;;;;;;
TAB2: JSR ADJUST      ; ADJUST COLUMN COUNT
        JSR OUTPUT2     ; DON'T GO TO SCREEN WHEN TABBING
        JMP FORCECR     ; SHARE SOME CODE. . .

NOTAB: PLA
        CLV
        PHP             ; SAVE 'NO TAB' INDICATION
NOTAB1: STA CHARACTER   ; (FORCE CR REENTRY)
        PHA
        JSR OUTPUT1     ; ENTER AFTER CMD SEQ CHECK
        JSR ADJUST
        PLA
        EOR #$8D        ; WAS IT A CR?
        ASL A
        BNE FORCECR
        STA COLBYTE,X   ; IF SO, RESET COLUMN TO 0
        STA CH

FORCECR: LDA STATEFLG,X  ; FORCE CR DISABLED?
        BPL SEREND
        LDA PWDBYTE,X   ; FORCE CR IF LIMIT REACHED
        BEQ SEREND      ; (FOR P8 POKE COMPATIBILITY)
        CLC
        SBC COLBYTE,X
        LDA #$8D
        BCC NOTAB1      ; BRANCH TO FORCE CR

SEREND: PLP
        BVS TABCHECK    ; BRANCH IF TABBING

        LDA MISCFLG,X   ; DON'T MESS WITH CURSOR
        BMI SEREND2     ;  WHEN VIDEO IS ON
        LDY COLBYTE,X
        ASL A
        BMI SETCH       ; SET CH TO VALUE OF COL FOR TABBING
        TYA
        LDY #0
        SEC
        SBC PWDBYTE,X
        CMP #$F8        ; WITHIN 8 CHARS OF PWIDTH?
        BCC SETCH
        ADC #$27        ; IF SO, ADJUST TO WITHIN 8 OF 40
        TAY
SETCH: STY CH

SEREND2: JMP BASICEXIT   ; THAT'S ALL

;;;;;;;;;;;;;;;;;;;;;;;;
; PASCAL ENTRY ROUTINE ;
;;;;;;;;;;;;;;;;;;;;;;;;
PENTRY: STX MSLOT
        STY SLOT16
        LDA #0
        STA STSBYTE,X
        RTS

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; SIC MODE PRINTER WIDTH TABLE ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PWDTBL: .byte $29         ; 40 COLUMNS
        .byte $48         ; 72 COLUMNS
        .byte $50         ; 80 COLUMNS
        .byte $84         ; 132 COLUMNS
;;;;;;;;;;;;;;;;;;;;;;;;
; PASCAL WRITE ROUTINE ;
; (DOUBLES AS PASCAL   ;
;  1.0 ENTRY POINT)    ;
; -MUST BE AT SC9AA-   ;
;;;;;;;;;;;;;;;;;;;;;;;;
PASCALWRITE: STA CHARACTER
        JSR PENTRY
        JSR OUTPUT
        JMP PASEXIT     ; LOAD X-REG WITH ERROR BYTE & RTS

;;;;;;;;;;;;;;;;;;;;;;;;;
; COLUMN ADJUST ROUTINE ;
; (PPC, SIC MODES ONLY) ;
;;;;;;;;;;;;;;;;;;;;;;;;;
ADJUST: LDA CHARACTER
        EOR #$08        ; BACKSPACE?
        ASL A
        BEQ DECRCOL     ; IF SO, DECREMENT COLUMN
        EOR #$EE        ; DELETE? ($FF, RUB)
        BNE CTRLTST
DECRCOL: DEC COLBYTE,X   ; DECREMENT COLUMN COUNT
        BPL ADJRTS
        STA COLBYTE,X   ; DON'T ALLOW TO GO BELOW 0
ADJRTS: RTS
CTRLTST: CMP #$C0        ; DON'T INCREMENT COLUMN COUNT FOR
        BCS ADJRTS      ;  CONTROL CHARACTERS
        INC COLBYTE,X
        RTS
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
; ROUTINE TO PROCESS SPECIAL INPUT CHARS ;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CKINPUT: LDA MISCFLG,X
        AND #$08        ; INPUT CTL CHARS ENABLED?
        BEQ CIEND

        LDA STATEFLG,X
        LDY CHARACTER
        CPY #$94        ; CTL-T?
        BNE CKINPUT1
        ORA #$80        ; SET TERMINAL MODE
        BNE CKINPUT2    ; <ALWAYS>

CKINPUT1: CPY #$92       ; CONTROL-R?
        BNE CIEND
        AND #$7F        ; RESET TERMINAL MODE
CKINPUT2: STA STATEFLG,X
CIEND: RTS

; TERM.

